class Solution {
public:
 int miceAndCheese(vector<int>& reward1, vector<int>& reward2, int k) {
  int total=accumulate(reward2.begin(),reward2.end(),0);
  vector<int> gain;
  for(int i=0;i<(int)reward1.size();++i)gain.push_back(reward1[i]-reward2[i]);
  sort(gain.rbegin(),gain.rend());
  for(int i=0;i<k;++i)total+=gain[i];
  return total;
 }
};
